/**
 * ResponsiveImage — AVIF→JPG <picture> that serves:
 *   • phones   → tiny (320–640w) files, ~20-60 KB
 *   • desktops → large (1080–1920w) files
 *   • 4K screens → 3840w (and the 5000w master for the two 4K cobs)
 *
 * Files are generated by client/scripts/optimize-media.sh.
 * `stem` is the file name without extension, e.g. "cob-sky-4k".
 */
export default function ResponsiveImage({
  stem,
  alt = "",
  sizes = "100vw",
  widths = [640, 1080, 1920, 3840],
  masterWidth = 5000, // width descriptor of the untouched master file
  masterFile, // defaults to `${stem}.jpg`
  className = "",
  style,
  eager = false,
  fetchPriority,
  objectFit = "cover",
  objectPosition,
  decoding = "async",
  onLoad,
}) {
  const master = masterFile ?? `${stem}.jpg`;
  const avifSrcSet = widths.map((w) => `/media/images/${stem}-${w}.avif ${w}w`).join(", ");
  const jpgSrcSet = [
    ...widths.map((w) => `/media/images/${stem}-${w}.jpg ${w}w`),
    `/media/images/${master} ${masterWidth}w`,
  ].join(", ");
  // Sensible no-srcset fallback: largest rendition ≤1080w that actually exists
  const fallbackW = [...widths].reverse().find((w) => w <= 1080) ?? widths[0];

  return (
    <picture>
      <source type="image/avif" srcSet={avifSrcSet} sizes={sizes} />
      <img
        src={`/media/images/${stem}-${fallbackW}.jpg`}
        srcSet={jpgSrcSet}
        sizes={sizes}
        alt={alt}
        className={className}
        style={{ ...style, objectFit, objectPosition }}
        loading={eager ? "eager" : "lazy"}
        decoding={decoding}
        fetchPriority={fetchPriority}
        onLoad={onLoad}
      />
    </picture>
  );
}
